DEFERRED={w:'较冷门的医学、生物或宗教术语，先保留原词典资料。' for w in ['xeroderma','xerosis','xerasia','xerochilia','xeromorph','xerophagy','xerophile','xerophthalmia','xerophyte']}
DEFERRED.update({'frugivorous':'较专门的食果性动物术语，暂略。','tetradrachm':'专门古币名称，先掌握 drachma。','didrachm':'专门古币名称，先掌握 drachma。','drachm':'旧重量义拼法已并入 dram，读音与来源一起解释。','tympani':'timpani 的拼写变体已并入该词，不另重复。','plumate':'罕见的羽状形容词，暂略。','Leo':'人名、星座名等专名，暂不单列通用精讲。','Leopold':'日耳曼人名，主要接“人民、勇敢”成分，不因近似 leo 就归作狮子词根后代。','siphonoglyph':'腔肠动物解剖中的专门术语，暂略。'})
