def rootwords(i,extra=()):return list(dict.fromkeys([w for w in ASSIGN['roots'][i]['family'] if w not in DEFERRED and '-' not in w]+list(extra)))
def rootexclude(i):
 r=ASSIGN['roots'][i];c=CATALOG[r['id']];return {w:DEFERRED[w] for w in set(r['family'])|set(c['family'])|set(c['words'])|set(c['unmatched']) if w in DEFERRED}
XER_ROOT=dict(id='C1668',meaning='干；干燥',core='没有液体显影的粉末成像，让“干”进入了现代办公室词汇。',image='希腊 xeros 干 + -graphy → xerography → Xerox 品牌 → xerox 复印；elixir 的更远来源通常联系 xerion 干燥粉末，但保留不确定性。',intro='xerography 是技术名称，xerox 是从品牌走向日常动作的用法。elixir 已离干燥的字面很远：它经阿拉伯语和中世纪拉丁语传来，现代常说仙药或令人恢复活力的东西。',forms='xero- 在这些英语词的开头读 /z/。elixir 的开头形态保留了阿拉伯语定冠词 al- 的历史痕迹，不适合按现代英语前缀随意拆分。',branches=[['干式静电复制','xerography'],['品牌转作动作','xerox'],['传统联系、远源未完全确定','elixir']],contrasts='xerography 不是所有复印、打印技术的总称。elixir 的奇效是历史信念或现代比喻，不能从词源推出药效。',practice='用 xerox 请人复印一页文件，再用 elixir 写一个明确的生活比喻；比较两个词分别经过了什么语言和命名阶段。',words=rootwords(258),exclude=rootexclude(258))
FRUCT_ROOT=dict(id='C0453',meaning='果实；收获；享用；有用与节俭',core='收获得到东西，人便能享用；懂得让东西发挥用处，又联系到节俭。',image='拉丁 frui → fructus → 古法语 fruit → 英语 fruit；fructus + -ose → fructose；frui → fruitio → fruition；frux／frug- → frugi → frugalis、frugalitas → frugal、frugality。',intro='fruit 是果实与成果，fruitful、fruitless 描述有没有收获。fruition 的现代实现义受到 fruit 联想影响，但原义是享用。frugal 一支早在拉丁语便走向实用、节俭，不是现代英语的 fruit 直接变出省钱。',forms='fruct- 保留古典词干，fruit 经法语发生简化；frug- 属相关的古典词形。frugality 有独立借入史，不能用英语词长来推断谁一定先出现。',branches=[['果实、味道与成果','fruit, fruity, fruitful, fruitless'],['计划终于实现','fruition'],['糖类名称','fructose'],['节用而不浪费','frugal, frugality, frugally']],contrasts='fruitless 说没有成果，pointless 说没有意义；frugal 常是节俭，stingy 更偏吝啬。fructose 是一种具体糖，不是全部水果糖分的统称。',practice='把一场 productive discussion 改说 fruitful discussion；再解释为什么 frugal 和 frugality 应在拉丁词干处分支，而不是强接在英语 fruit 后。',words=rootwords(259),exclude=rootexclude(259))
DRACH_ROOT=dict(id='C0345',meaning='一把所抓；古代重量与钱币名称',core='手中握住的一把，传统上被用来解释古代计量名称的来历。',image='希腊 drakhme → 拉丁 drachma；经 dragma、古法语 dragme／drame 的简化支线 → dram；较完整的古典词形 → drachma。',intro='dram 在现代阅读里常是一点威士忌，在旧资料里也可以是单位；drachma 则多出现在古币和希腊旧货币语境。两词有历史联系，不能因此把现代单位和日常一小杯混用。',forms='drach- 不是可以随意加到英语单词前面的活跃前缀。drachm 这个重量拼法读 /dræm/，已并入 dram；drachma 中的 ch 读 /k/。',branches=[['词形缩短：少量酒与旧单位','dram'],['保留古典形态：钱币名称','drachma']],contrasts='a dram of whisky 不保证固定容量；旧 dram 换算必须先知道采用什么制度。drachma 的货币义也不等同于古代重量在所有时期的数值。',practice='分别写一位旅行者点酒和一位考古学者看古币的句子；说明为何两处不能交换 dram 与 drachma。',words=rootwords(260),exclude=rootexclude(260))
MOL_ROOT=dict(id='C0756',meaning='磨；研碎',core='磨石不停转，把整颗谷物变成细碎可用的材料。',image='拉丁 mola → molina／molinum → 古英语 mylen → mill → miller、milling；mola → molaris dens → molar 臼齿；远同源日耳曼支线 melu → meal 谷粉。',intro='mill 是磨坊、研磨机，也扩展为一些工厂；molar 臼齿像口中的小磨盘。meal 的谷粉义属于磨碎这条线，最常见的一餐义另接古英语 mæl。molar 的化学义也另接 mole，不从牙齿推出。',forms='mill 是早期借词在英语中的演变，不是简单替换 mol- 的元音。meal 的两个来源、molar 的两条现代用法都在各自词条中并列解释。',branches=[['磨坊、加工与人群转动','mill, miller, milling'],['口中的磨盘；另辨摩尔义','molar'],['磨出的谷粉；另辨一餐义','meal']],contrasts='mol- 磨与拉丁 moll- 软、moles 物体的量不能只凭字母近似合并。milling 在金属加工中是铣削，不能一律译成磨粉。',practice='比较 a hot meal 与 corn meal，再比较 a molar tooth 与 molar mass；为每一对指出哪一个义项接磨碎词族。',words=rootwords(261),exclude=rootexclude(261))
MULG_ROOT=dict(id='C0770',meaning='挤奶；乳状液体',core='挤出的奶状液体，成为后来乳液命名的直观画面。',image='拉丁 mulgere 挤奶 → emulgere → 分词词干 emuls- → 近代拉丁 emulsio／法语 émulsion → emulsion；英语 emuls- + -fy → emulsify → emulsifier、emulsification。',intro='emulsion 是乳液，emulsify 是使其形成，emulsifier 是帮助形成或稳定乳液的物质、设备，emulsification 是乳化过程。现代这些词不要求里面含奶。',forms='mulg- 与 muls- 对应古典动词与分词词干。emulsion 读 /ʃ/；emulsify、emulsifier、emulsification 中则读 /s/。-ify 转名词时对应 -ification。',branches=[['得到的体系','emulsion'],['形成乳液','emulsify'],['起作用的物质或设备','emulsifier'],['过程名称','emulsification']],contrasts='溶解 dissolve 与乳化 emulsify 不同；乳液里的分散相仍是小液滴。摄影乳剂 emulsion 属传统名称，不严格等同于液体分散在液体中。',practice='用 oil 和 water 分别造一个含 emulsify 的动作句、一个含 emulsification 的过程句，再指出 emulsifier 和 emulsion 谁是帮手、谁是得到的体系。',words=rootwords(262),exclude=rootexclude(262))
TYMPAN_ROOT=dict(id='C1568',meaning='鼓；敲击',core='一面鼓既提供声音，也提供一层张开薄膜的形象。',image='希腊 tympanon → 拉丁 tympanum → 英语专业用法 tympanum／tympanic；拉丁 → 意大利 timpano／timpani → timpani → timpanist；希腊相关形式经法语 timbre → 英语音色义。',intro='音乐中的 timpani 是定音鼓，timpanist 是演奏者；timbre 是音色。解剖中的 tympanum、tympanic 与鼓膜和鼓室有关；建筑 tympanum 则另有框出装饰面的用途。它们不是按现代英语单词长度排成一条线。',forms='tympan-、timpan- 是不同语言与拼写传统留下的形态。timpani 的末尾 i 来自意大利语复数；tympani 是可合并记忆的拼写变体。timbre 保留法语拼写，常读 /ˈtæmbə/。',branches=[['乐器与演奏者','timpani, timpanist'],['声音质感','timbre'],['解剖与建筑名称','tympanum, tympanic']],contrasts='音色 timbre 不等于音高 pitch 或音量。鼓膜是一层膜，鼓室是腔隙；tympanic membrane 与 tympanic cavity 最后的名词不可互换。',practice='描述两件乐器同音高但不同 timbre，再用 tympanic membrane 标出耳中与鼓面相似的部位。',words=rootwords(263),exclude=rootexclude(263))
PLUM_ROOT=dict(id='C1076',meaning='羽毛',core='羽毛从细窄的根部展开，既像装饰，也像一股舒展的烟。',image='拉丁 pluma → 古法语 plume → 英语 plume；古法语 plume + -age → plumage → 英语 plumage。',intro='plume 可以是一根长羽毛、羽饰，也可以是一股烟或水流。plumage 把一只鸟的羽毛作为整体来讲，特别适合说颜色、季节和外观。',forms='plumage 中的 -age 是法语集合性构词的痕迹，英语借入的是完整词。不要把羽毛词根与 plum 李子、plumb 铅垂的近形词混成一族。',branches=[['单根、羽饰与羽状流体','plume'],['鸟的整体羽衣','plumage']],contrasts='a plume 可以数，plumage 通常作为整体不可数。smoke 是烟这种物质，a plume of smoke 进一步说它形成的一股形状。',practice='分别用 plume 和 plumage 描写一顶羽毛帽与一只鸟，再用 a plume of smoke 把形状联想迁移到烟。',words=rootwords(264),exclude=rootexclude(264))
LEON_ROOT=dict(id='C0665',meaning='狮子',core='狮子的外形、威仪和引人注目的形象，分别进入了描写和社交语言。',image='希腊 leon → 拉丁 leo／leon- → 古法语 lion → 英语 lion → lioness、lionize；拉丁 leoninus → leonine；法语 dent de lion 狮子牙 → dandelion。',intro='lion 是基础动物名，lioness 说明雌性，leonine 是像狮子，lionize 则是把人捧为名流。dandelion 的狮子不在花朵上，而在被比作狮牙的锯齿形叶缘。',forms='leon- 是古典词形，lion 是经法语传来的常用形态。lionize／lionise 是两种拼写；lioness 中 -ess 标雌性，不能理解为幼小。',branches=[['动物名称','lion, lioness'],['外形与气势','leonine'],['追捧名人','lionize'],['叶缘的狮牙比喻','dandelion']],contrasts='lionize 不表示训练人勇敢；leonine 也不必带凶狠意味。近形专名 Leopold 主要属于另一套日耳曼构词，不按 leo 的拼写强归。',practice='把一位人物写得 leonine，再另写他受到媒体 lionized 的情景；前一句写外观或气势，后一句写别人对他的态度。',words=rootwords(265),exclude=rootexclude(265))
